INSERT INTO `sorts_veg` VALUES (1,'Морква Паризький ринок','06-10','06-15','08-10','08-15','70 - 75 днів ',1,'Оранжевий','30-50 г','Сорт використовується як для консервування, так і для вживання у свіжому вигляді.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/morkov-parijskiy-rynok-semena2.jpg?1734963120','Плоди відрізняються своєю незвичайною округлою формою і маленькими розмірами (2-4 см в діаметрі). М\'якоть яскраво-помаранчева, шкірка тонка і практично непомітна.'),(2,'Морква амстердамська','06-15','06-25','08-15','08-25','75 - 85 днів ',1,'Оранжевий','100-200 г','Сорт використовується для вживання у свіжому вигляді','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/morkov-stolovaya-amsterdamskaya-semena_1.jpg?1734963840','серцевина маленька, м\'якоть ніжна, соковита'),(3,'Морква Нантес Скарлет','06-10','06-20','08-10','08-20','70 - 80 днів',1,'Оранжевий','80-120 г','Сорт використовується для вживання у свіжому вигляді','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/morkov-nantes-skarlet_1.jpg?1734964200','Плоди моркви виростають довжиною до 18 см. Для них властивий гарний помаранчевий колір і відмінний товарний вигляд. Сорт високоврожайний і стійкий до утворення стрілок'),(4,'Морква Абако F1','06-20','06-25','08-20','08-25','80 - 85 днів ',1,'Оранжевий','100-225 г','Сорт придатний для комерційного виробництва, тривалого зберігання, переробки на дитячі соки, пюре.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/morkov-abako-f1_1.jpg?1734964560','Плоди виростають помірно великі до 16 см, забарвлення м\'якоті темно-помаранчева, внутрішня частина - з червонуватим відтінком через високий вміст каротину'),(5,'Морква Артек','06-05','06-25','08-05','08-25','65 - 85 днів ',1,'помаранчево-червоний','80 - 130 г','Сорт використовується для вживання у свіжому вигляді','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/morkov-artek_1.jpg?1734964560','Плоди цього сорту відрізняються соковитістю і відмінним смаком.'),(6,'Морква оленка','06-25','07-10','08-25','09-10','85 - 100 днів ',1,'Оранжевий','80 - 110 г','Сорт використовується для вживання у свіжому вигляді','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/morkov-alenka_1.jpg?1734964920','Відрізняється високою врожайністю і стійкістю до хвороб і низьких температур. Серединка у плодів виражена слабко.'),(7,'Морква каріні','07-01','07-10','09-01','09-10','90 - 100 днів ',1,'Оранжевий','100 - 150 г','Рекомендовані для вживання у свіжому вигляді, приготування дієтичного та дитячого харчування, віджимання соку, а також інших видів кулінарної переробки.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/morkov-karini_1.jpg?1734964920','Коренеплоди насичено-помаранчеві, циліндричні, тупоносі, соковиті і солодкі.'),(8,'Морква лагуна F1','06-20','06-25','08-20','08-25','80 - 85 днів ',1,'Оранжевий','100 - 130 г','Використовують вживання в свіжому вигляді, переробки, консервування та заморозки. ','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/morkov-laguna-f1_1.jpg?1734964920','Коренеплоди довжиною 17 - 20 см. Форма циліндрична, рівна, витягнута. Колір м\'якоті: інтенсивно-оранжевий. Серцевина дуже маленька.'),(9,'Морква сімейний сад F1','06-20','06-30','08-20','08-30','80 - 90 днів ',1,'Оранжевий','100 - 200 г','Можна вирощувати як в комерційних цілях, так і для домашнього вжитку. Підходить для вживання дітям - у свіжому вигляді й у якості соків або пюре.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/morkov-semeynyy-sad-f1_1.jpg?1734965280','Плоди середні - довжиною до 16 см. Серединка помаранчево-червона, що свідчить про високий вміст каротину.'),(10,'Берлікумер','07-20','08-10','09-20','10-10','110 - 130 днів ',2,'Оранжевий','120 - 190 г','Використовують вживання в свіжому вигляді, переробки, консервування та заморозки. ','https://images.prom.ua/4135985376_nasinnya-morkvi-berlikumer.jpg','Коренеплід довгий, циліндричний з тупим кінчиком. Серцевина помаранчева. Придатний для тривалого зберігання. При зберіганні вміст каротину збільшується у 1,5 разу. Культура вимоглива до вологи та родючих пухких ґрунтів. Висівати у вологий ґрунт на глибину 2-3 см.'),(11,'Морква вітамінна 6','07-10','07-30','09-10','09-30','100 - 120 днів ',2,'Оранжевий','60 - 160 г','Рекомендований для вживання у свіжому вигляді та для зимового зберігання.','https://images.prom.ua/4134542814_nasinnya-morkvi-vitaminna.jpg','Коренеплід помаранчевий, циліндричний, тупокінцевий, довжиною 15 см, майже повністю занурений у ґрунт. М\'якуш оранжево червоний, соковитий, солодкий. Вимагає зрошення та розпушування ґрунту. Культура вимоглива до вологи та родючих, пухких ґрунтів. Смакові якості коренеплодів добрі.   Висівати у вологий ґрунт на глибину 2-3 см.'),(12,'Морква каротель','06-23','07-15','08-23','09-15','83 - 105 днів ',2,'оранжево-червоний','80 г','Цей сорт рекомендується для споживання у свіжому вигляді, а також для переробки в соки та пюре.','https://images.prom.ua/4139867104_nasinnya-morkvi-karotel.jpg','Коренеплід довжиною 10-12 см, насичено оранжево-червоного кольору, тупокінцевий. М\'якуш соковитий, дуже солодкий, хрумкий. Серед середньоранніх сортів відрізняється лежкістю коренеплодів та збереженням у них вітамінів. Висівати у вологий ґрунт на глибину 2-3 см.'),(13,'Морква ласуня','06-20','07-14','08-20','09-14','80 - 104 днів ',2,'червоно-жовтогарячий','60 - 155 г','Призначений для використання у свіжому вигляді, переробки, зберігання.','https://images.prom.ua/4164461134_nasinnya-morkvi-lasunya.jpg','Коренеплід циліндричний, інтенсивного червоно-жовтогарячого кольору, соковита, солодка, довжиною 20 см.  Культура вимоглива до вологи та родючих пухких ґрунтів. Для отримання дружних сходів насіння рекомендується змочувати у воді кімнатної температури на добу, потім просушувати при температурі 15-16°С до сипучості. Висівати у вологий ґрунт на глибину 2-3 см.'),(14,'Морква лосиноострівська','07-10','07-20','09-10','09-20','100 - 110 днів ',2,'червоно-жовтогарячий','70 - 150 г','Сорт використовується для вживання у свіжому вигляді','https://images.prom.ua/4164472132_nasinnya-morkvi-losinoostrivska.jpg','Коренеплід циліндричний, інтенсивного червоно-жовтогарячого кольору, соковита, солодка, довжиною 15-25см. Один із найкращих столових сортів. Культура вимоглива до вологи та родючих пухких ґрунтів. Для отримання дружних сходів насіння рекомендується змочувати у воді кімнатної температури на добу, потім просушувати при температурі 15-16°С до сипучості. Висівати у вологий ґрунт на глибину 2-3 см.'),(15,'Морква Шантане','07-10','07-10','09-10','09-10','100 днів ',2,'оранжево-червоний','80 - 150 г','Сорт використовується для вживання у свіжому вигляді та зберігання','https://images.prom.ua/4133437242_nasinnya-morkvi-shantane.jpg','Коренеплід конічної форми, довжиною 14 см, оранжево-червоний, повністю занурений у ґрунт. Серцевина маленька. М\'якуш соковитий, яскраво-оранжевого кольору з високим вмістом цукру та каротину. Найкращий сорт для зимового зберігання. Культура вимоглива до вологи та родючих пухких ґрунтів. Сорт жаростійкий, стійкий до цвітіння та розтріскування. Висівати у вологий ґрунт на глибину 2-3 см.'),(16,'Морква червоний велетень','08-20','09-10','10-20','11-10','140 - 160 днів ',3,'оранжево-червоний','200 г','Підходить для приготування соку, придатні для тривалого зберігання.','https://images.prom.ua/4136091983_nasinnya-morkvi-chervonij.jpg','Коренеплоди конічні, довжиною 22-26 см. Серцевина невелика. М\'якуш червоно-оранжевий, дуже смачний, солодкий і соковитий. Сорт холодостійкий, невибагливий, стійкий до цвітіння та розтріскування коренеплодів. Культура вимоглива до вологи та родючих пухких ґрунтів. Висівати у вологий ґрунт на глибину 2-3 см.'),(17,'Морква флакке','07-20','08-10','09-20','10-10','110 - 130 днів',3,'оранжево-червоний','60 - 180 г','Використовують для тривалого зберігання, переробки та вживання у свіжому вигляді.','https://images.prom.ua/4164399087_nasinnya-morkvi-flakke.jpg','Коренеплоди тупоконічні, насиченого оранжево-червоного кольору, довжиною 20-25 см, вирівняні, гарна лежкість, відмінний смак, зовні привабливі. М\'якуш оранжево-червоний. Для відкритого ґрунту. Культура вимоглива до вологи та родючих пухких ґрунтів. Для отримання дружних сходів рекомендується змочувати насіння у воді кімнатної температури на добу, потім просушувати при температурі 15-16С до сипучості. Висівати у вологий ґрунт на глибину 2-3 см.'),(18,'Морква флайові','09-05','09-25','11-05','11-25','155 - 175 днів ',3,'яскраво-жовтогарячий','150 - 200 г','Рекомендується для вживання у свіжому вигляді, переробки та зберігання.','https://images.prom.ua/4133480440_nasinnya-morkvi-flajovi.jpg','Коренеплоди циліндричні, довжиною до 25 см. М\'якуш яскраво-жовтогарячий, соковитий, солодкий. Цінність сорту: висока врожайність, вирівняність та чудові смакові якості коренеплодів. Культура вимоглива до вологи та родючих пухких ґрунтів. Висівати у вологий ґрунт на глибину 2-3 см.'),(19,'Морква віта лонга','07-10','07-20','09-10','09-20','100 - 110 днів ',3,'Оранжевий','95 - 130 г','Рекомендується для свіжого споживання та зберігання.','https://images.prom.ua/4136113676_nasinnya-morkvi-vita.jpg','Бадилля потужне. Коренеплід довгий – 25 см, товстої, конічної форми. Поверхня злегка ребриста, забарвлення м\'якоті та серцевини помаранчеве. Головка плоска, трохи виступає над поверхнею грунту, озеленена. Смакові властивості моркви Віта Лонга високі. '),(20,'Морква карлена','08-30','09-10','10-30','11-10','150 днів ',3,'Оранжевий','80 - 150 г','Сорт придатний для споживання у свіжому вигляді, переробки та тривалого зберігання.','https://images.prom.ua/4134643784_nasinnya-morkvi-karlena.jpg','Коренеплід довгий, конічної форми, з тупим кінчиком. Забарвлення коренеплоду помаранчеве, серцевина невелика та середнього розміру, помаранчевого забарвлення. Смакові якості добрі. Цінність сорту: висока врожайність, вирівняність коренеплодів та їх хороші смакові якості. Культура вимоглива до вологи та родючих пухких ґрунтів. Висівати у вологий ґрунт на глибину 2-3 см. ');
INSERT INTO `sorts_veg` VALUES (21,'СІР F1 / SIR F1 - Капуста Білоголова, Clause','06-14','06-19','08-14','08-19','60 днів ',4,'зелений','1,5 - 2 кг','Чудово підійде для використання у свіжому вигляді та квашення завдяки своєму солодкому і ніжному смаку','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/f/i/file_2_5.webp','Урожайний сильнорослий гібрид білокачанної капусти, голівки правильної округлої форми, тверді. Листя щільне міцне з восковим нашаруванням. Коренева система сильно розвинена. Характеризується високими якостями транспортування і нетривалим терміном зберігання без втрати товарності. Не схильний до розтріскування, висока стійкість до фузаріозу, завдяки високому польовому здоров\'ю. Висока стійкість до кліматичних умов вирощування в тому числі до різких понижень температури і нестачі вологи. Гарне польове збереження. Придатний до вирощування на важких за механічним складом ґрунтах.'),(22,'ЕКСПРЕСС / EXPRESS — Капуста Білоголова, Hortus','06-25','06-30','08-25','08-30','75-80 днів ',4,'зелений','1 - 1,2 кг','Для отримання раннього врожаю','https://agrolife.ua/media/mf_webp/jpeg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/6/7/6759_pic.webp','Плоди захищені восковим покриттям. Головки формуються світло-зеленого кольору, в розрізі білі.'),(23,'ЄТМА F1 / JETMA F1 - Капуста Білоголова, Rijk Zwaan','06-05','06-10','08-05','08-10','45-50 днів ',4,'зелений','0,7 - 1,5 кг','Найбільш вдалий в сфері використання в свіжому вигляді.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/j/e/jetma-rz-f1-1.webp','Голівка щільна, компактна, округла, красивого світло-зеленого кольору.'),(24,'ЕЛІЗА F1 / ELIZA F1 – Капуста Білокочанна, Sakata','06-03','06-08','08-03','08-08','43-48 днів ',4,'зелений','0,6 -1,2 кг','Для отримання надранньої продукції!','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/7/1/71680576_2843517995699142_5232195023310684160_o.webp','пристосований до різних умов і термінів вирощування. Довго зберігається в полі, що не характерно для інших ранніх гібридів. Переносить короткочасні заморозки. Для отримання надранньої продукції рекомендується висаджувати під укриття (теплиці, плівка, агроволокно). Сорт капусти Еліза характеризується наявністю злегка піднятої розетки. Листя невеликого розміру має хвилястий край і пухирчасту поверхню. Воно формує щільний качан округлої форми (може бути злегка жовтуватим всередині). У кожній голівці є невеликий качан. Приємний солодкуватий смак. Невибагливість у догляді (завдяки стійкості до несприятливих погодних умов, шкідників). Щоб отримати рясний урожай, насіння висаджувати слід уже на початку березня. При цьому капусту вирощують переважно розсадним методом. Якщо сіяти насіння в ґрунт, рекомендується вибирати схему 60х40 см і починати у другій половині травня. Варто пам\'ятати про використання комплексних добрив, регулярний полив та догляд.'),(25,'ПАНДІОН F1 / PANDION F1 -Капуста Білокачанна, Seminis','06-08','06-13','08-08','08-13','48-53 днів',4,'зелений','1-2 кг','Для споживання в свіжому вигляді.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/p/a/pandion_obr.webp','Качани округлі і щільні, ніжного зеленого забарвлення, внутрішня структура з тонкими листям і короткою кочергою, дуже довго не розтріскується. відрізняється чудовим збереженням в польових умовах і вирівняними за формою і розміром качанами. Стійкий до розтріскування і до судинного бактеріозу. Рекомендується для вирощування в плівкових теплицях і у відкритому ґрунті для отримання надранньої продукції.'),(26,'СЛАВА / SLAVA — Капуста Білоголова, Hortus','08-05','08-10','10-05','10-10','110-115 днів.',5,'зелений','4,5 кг','Сорт призначений для короткочасного зберігання (впродовж 3 місяців); для свіжого вигляду і квашення.','https://agrolife.ua/media/mf_webp/jpeg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/1/5/153643-0.webp','Головки округлі і плоско-округлі, щільні. Внутрішній качан середнього розміру. Сорт середньостійкий до основних хвороб і стійкий до розтріскування.'),(27,'ГЛОРІЯ F1 / GLORIA F1 - Капуста Білокачанна, Syngenta','06-25','06-30','08-25','08-30','75-80 днів.',5,'зелений','2–5 кг','Рання реалізація у свіжому вигляді і зберігання до 4 місяців.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/8/f/8f15b447e0b23ddc9d61d5116969b9ae.webp','Гібрид Глорія F1 адаптований до різних кліматичних зон, стійкий до фузаріозу. Не вимагає інтенсивного живлення. Можливий прямий посів у відкритий ґрунт. Унікальний за призначенням гібрид з можливістю посіву в два терміни: ранній посів — на річну реалізацію, пізній посів — на зберігання. Зберігає відмінні товарні якості весь період збирання до пізньої осені. Головка округла, щільна.'),(28,'КОПЕНГАГЕН МАРКЕТ / COPENHAGEN MARKET — Капуста Білоголова, Satimex','08-05','08-10','10-05','10-10','115 днів.',5,'зелений','2,5 кг','Для споживання в свіжому вигляді і для переробки.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/k/o/kopenhahen-market-semena-kapusty-bk-srednei-satimex.webp','Плід щільний, світло-зелений, округлий, масою до 2,5 кг. У рослини є качан невеликого розміру. Сорт стійкий до розтріскування. Прекрасні смакові якості, товарний вигляд і можливість при мінімальних витратах отримувати стабільний, високий врожай. Сорт стійкий до розтріскування. Період збирання (міс. ): липень, серпень. Для вирощування у відкритому ґрунті'),(29,'БРОНКО F1 / BRONCO F1 - Капуста Білоголова, Bejo','06-20','06-25','08-20','08-25','80 днів.',5,'зелений','2,5-3,0 кг','Універсальний.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/b/r/bronco_f1_f1_bronco_-_gz008324.webp','Качани мають відмінну щільну внутрішню структуру і короткий качан. Завдяки добре розвиненій кореневій системі, даний гібрид можна вирощувати в посушливих регіонах. Стійкий до фузаріозу.'),(30,'КАББІС F1 / KABBIS F1 — Білоголова Капуста, Hazera','06-20','06-25','08-20','08-25','80-85 днів.',5,'зелений','3-5 кг.','Для реалізації на свіжому ринку і вживання у свіжому вигляді.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/k/a/kabbis.webp','Головки вирівняні за формою, щільні, яскраво-зеленого кольору. Листя м\'яке, але щільне, солодке і соковите. стійкий до розтріскування і підвищеної температури.'),(31,'АНКОМА F1 / ANCOMA F1 - Капуста Білоголова, Rijk Zwaan','08-10','08-25','10-10','10-25','120-135 днів',6,'зелений','3-4 кг','Для засолювання і нарізання в салати. Найбільш вдалий в сфері використання в свіжому вигляді і квашення завдяки своєму привабливому і ніжному смаку.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/a/n/ancoma-f1-2.webp','Однорідні, щільні, компактні, округлої форми. листя щільне, міцне з восковим нальотом. Рекомендується для вирощування під укриттям у вигляді плівки, агроволокна або теплиці, так як в цьому випадку гібрид здатний показувати найвищі показники врожайності. Характеризується високими якостями транспортування і тривалим терміном зберігання без втрати товарності - 4-5 місяці. Не схильний до розтріскування, висока стійкість до фузаріозу, завдяки високому польовому здоров\'ю. Висока стійкість до кліматичних умов вирощування в тому числі до ґрунтової та повітряної посухи. '),(32,'ХАРКІВСЬКА ЗИМНЯ / KHARKIV WINTER — Капуста Білоголова, Hortus','09-10','09-20','11-10','11-20','150-160 днів.',6,'зелений','3,0 -4,0 кг','Універсальне значення. Для використання у свіжому вигляді, квашення і тривалого зберігання.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/k/h/kharkovskaia-zimniaia-semena-kapusty-bk-pozdnei-euroseed-_1_.webp','Качани дуже щільні, округлої форми. Вміст сухих речовин 8,6%, цукру - 5,25%. Відносно стійкий до бактеріозів. Стійкість до хвороб: до враження судинним бактеріозом, плямистим некрозом і при тривалому зберіганні. Стійкість до розтріскування. Посів: квітень, травень. Період збирання (міс.): вересень.'),(33,'БІРЮЗА / BIRJUZA — Капуста Білоголова, Satimex','08-20','09-10','10-20','11-10','130-150 днів.',6,'зелений','3,5-5 кг.','Придатний для використання у свіжому вигляді, переробки і зберігання до травня-червня.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/s/5/s58505468.webp','формує однорідні, тверді головки, світло-зеленого забарвлення, з сильним восковим шаром високої смакової якості. Стійкий до розтріскування, і грибкових хвороб. Стійкість до фузаріозного в\'янення. Період збирання (міс.): вересень-листопад.'),(34,'КОРОНЕТ F1 / KORONET F1 — Капуста Білокачанна, Sakata','07-30','08-10','09-30','10-10','110-120 днів',6,'зелений','2,5-4 кг','Довготривале зберігання 120-150 днів в нормальних умовах.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/2/e/2e1746ae5f8c933c7a964146abd73b14.webp','Качани вирівняні, високої щільності, округлої форми. Мають свіжий вигляд навіть після обриву листя. Пристосований до різних умов вирощування, переносить високі і низькі температури. Стійкий до фузаріозу і внутрішнього некрозу листя.'),(35,'АДАПТОР F1 / ADAPTOR F1 - Капуста Білокачанна, Syngenta','07-25','07-30','09-25','09-30','115-120 днів.',6,'зелений','3-4 кг',' Реалізація в свіжому вигляді, переробка та зберігання до 6 місяців.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/a/d/adaptor_1_obr.webp','Качан має округлу, злегка приплющену форму і світло-зелене забарвлення. Білокачанна капуста щільна всередині, при цьому у неї ніжні та соковиті листи (можливий восковий наліт середньої інтенсивності). Для гібрида характерна ніжка середнього розміру і невеликий качан. Гібрид добре переносить недостачу азотного харчування. Стійкий до пошкодження трипсом. Стійкий до фузаріозу.'),(36,'АУ ПРОДЮСЕР / AU PRODUCER — Кавун, LibraSeeds','06-10','06-15','08-10','08-15','70-75 днів',7,'зелений','8-12 кг','Кавун підходить для реалізації на свіжому ринку, кулінарної переробки, соління, квашення, консервації.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/1/_/1__2.webp','Він невибагливий у догляді, висаджується на різних ґрунтах і характеризується періодом вегетації 70-75 днів. Це міцна і потужна баштанна культура з добре розвиненою кореневою системою і довгими стеблами. Продюсер – це відмінний варіант посадок на суходолах. Він активно зав\'язує пагони без штучного поливу або підживлення. Дозрілий кавун являє собою великий овал з темно-зеленими смугами плода, вагою до 12 кг. У нього соковита і м\'ясиста насичено-червона м\'якоть без пустот і волокнистості. Насіння кавуна Продюсер F1 - коричневе, тверде і нечисленне. Кавун продюсер набув популярності завдяки можливості вирощувати в різних кліматичних зонах країни. Він радує високою врожайністю завдяки сортовій стійкості до основних захворювань (несправжня борошниста роса, фузаріоз, стеблова гниль, антракноз).'),(37,'БАЛУ (КС 165) F1 / BALU (KS 165) F1 - Кавун, Kitano Seeds','06-05','06-10','08-05','08-10','65-70 днів.',7,'зелений','9-11 кг','Для свіжого споживання.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/_/s/_s_165_f1.webp','КС 165 F1 (KS 165 F1) є раннім сортом кавуна типу Кримсон Світ. Вирівняні плоди набувають округлої форми і мають темно-зелені смуги на зеленому фоні. Вони покриті міцною вегетативною масою. Крім того, що м\'якуш хрусткий, він ще щільний і дуже солодкий. Має тонку текстуру і яскраво-червоне забарвлення. У середнього плоду вага: 9-11 кілограм. Характеризується шкіркою середньої товщини і хорошою транспортабельністю. Відрізняється стійкістю до фузаріозу (раса 0,1) і антракнозу (раса 1). Дозволено перевезення за допомогою транспортного засобу. Перевагою вважають високий показник продуктивності, довгостроковий період реалізації і концентрований збір врожаю.'),(38,'ГУЕЛВА F1 / HUELVA F1 — Кавун, Rijk Zwaan','05-25','05-30','07-25','07-30','55-60 днів',7,'зелений','5-9 кг','Для свіжого споживання.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/h/u/huelva_full_huelva-3-512x350.webp',' Приваблива червона, соковита м\'якоть з підвищеним вмістом цукру. Глибокий темно-зелений колір шкірки. Висока польова стійкість до несприятливих умов вирощування.'),(39,'ЛІВІЯ F1 / LIVIA F1 - Кавун, Clause','06-02','06-05','08-02','08-05','62-65 днів',7,'зелений','10-12 кг.','Для споживання в свіжому вигляді.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/a/r/arbuz-livia-2_1.webp','Плоди округлої форми в середньому 30х25см. Внутрішніх пустот не має (генетична особливість). Товщина шкірки середня, дуже щільна, темні смуги переважають над світлими, забезпечуючи стійкість до сонячних опіків. Плоди темного кольору. Всесезонний гібрид! Показує найкращі результати при вирощуванні у плівкових тунелях та у відкритому ґрунті протягом усього польового сезону.'),(40,'ШУГА БЕЙБІ / SUGAR BABY — Кавун, SAIS','06-10','06-10','08-10','08-10','70 днів',7,'зелений','4-5 кг','Для споживання в свіжому вигляді.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/s/h/shuha-bebi-semena-arbuza-hortus.webp','Плоди овальні, середньої величини, вагою 4-5 кг. Шкірка тоненька, але міцна, однорідного темно-зеленого забарвлення. М\'якоть яскраво-червоного кольору, ніжної структури, соковита і солодка. Стійкість до фузаріозу. Соковитий корм для великої рогатої худоби і для промислового отримання пектину. Здатність насіння проростати при зниженій температурі. Період збирання (міс. ): серпень-вересень');
INSERT INTO `sorts_veg` VALUES (41,'ЧАРЛЬСТОН ГРЕЙ / CHARLESTON GRAY — Кавун, SAIS','06-25','06-30','08-25','08-30','85-90 днів',8,'зелений','11-13 кг','Для використання в свіжому вигляді.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/c/h/charlston-hrei-semena-arbuza-sais.webp','Плоди подовжені, світло-зеленого кольору. М\'якоть червона, соковита, щільна, солодка на смак, шкірка середньої товщини. Сорт стійкий до антракнозу і фузаріозу'),(42,'ТОПГАН F1 / TOPGAN F1 — Кавун, Syngenta','05-28','06-01','07-28','08-01','58-62',8,'зелений','8-10 кг.','Для споживання в свіжому вигляді.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/t/o/top-han-f1-semena-arbuza-tip-krimson-svit-syngenta-_3_.webp','Плоди мають овальну форму і червону м\'якоть, у якій високий вміст цукру. Стійкий до різних видів захворювань: антракноз (Co: 1) і фузаріозне в\'янення (Fon: 0, 1)'),(43,'БАНІР (КС 1819) F1 / BANIR (KS 1819) F1 - Кавун, Kitano Seeds','06-10','06-15','08-10','08-15','70 - 75 днів',8,'зелений','10-12 кг','Для реалізації на ринку, в супермаркетах, а також для тривалого зберігання і транспортування на великі відстані.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/1/8/1819.webp','Плоди овальної форми. Шкірка середньої товщини, але щільна. М\'якуш дуже солодкий, темно-червоного кольору з щільною структурою. У плодах насіння середнього і дрібного розміру, чорне. Такий кавун стійкий до антрактозу і фузаріозу.'),(44,'ФАРАО F1 / FARAO F1 — Кавун, Syngenta','06-05','06-10','08-05','08-10','65-70 днів.',8,'зелений','15-18 (до 35) кг.','Для споживання в свіжому вигляді.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/f/a/farao-f1-semena-arbuza-tip-krimson-svit-syngenta-_1_.webp','Плід подовженої форми. Яскраво-червона хрустка м\'якоть з високим вмістом цукру, дрібне насіння. Стійкість до фузаріозного в\'янення (Fon: 0, 1) і антракнозу (Co 1)'),(45,'ФЕЛІП (51-019) F1 / FELIP (51-019) F1 – Безнасінний Кавун, Hazera','06-10','06-15','08-10','08-15','70-75 днів.',8,'зелений','7-9 кг','Для споживання в свіжому вигляді.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/9/5/95dcfa4364f7bdee7f1b154a35852ca5.webp','Шкірка світло-зеленого кольору з темними смужками. Форма плоду округла. Гібрид безнасінного кавуна. Товщина шкірки середня. Вирощується у весняно-літній період.'),(46,'ЕКСТЕЗІ F1 / EXTAZY F1 —Безнасінний Кавун, Hazera','06-20','06-25','08-20','08-25','80-85 днів',9,'зелений','1,5-2,5 кг','Для споживання в свіжому вигляді.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/4/6/46970551_2368413189853779_5047126514613616640_n.webp','Високий вміст цукру 13-14%. Плоди ідеальної округлої форми, шкірка блискучого темно-зеленого кольору з світло-зеленими смугами. М\'якуш щільний, хрусткий, насиченого темно-червоного кольору. Гібрид стійкий до вирощування в несприятливих погодних умовах (за наявності добре розвиненої кореневої системи у розсади)'),(47,'ДУМАРА F1 / DUMARA F1 - Кавун, Nunhems','06-12','06-18','08-12','08-18','72-78 днів',9,'зелений','12-16 кг','Для споживання в свіжому вигляді.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/_/f/_f1_2.webp','Подовжено-овальні, смугасті з переважанням темно-зеленої смуги, транспортабельні. М\'якуш хрусткий, соковитий, приємної структури з високим вмістом цукру і відмінними смаковими якостями, що являється «візитною карткою» цього кавуна. Мають тривале зберігання в полі без втрати якості і стійкість до утворення сонячних опіків. Має високий рівень польової стійкості до фузаріозного в\'янення (F.o.n. 0-1).'),(48,'ДАЙТОНА F1 / DAYTONA F1 – Кавун, Sakata','06-20','06-25','08-20','08-25','80-85 днів ',9,'зелений','12-14 кг','Для споживання в свіжому вигляді.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/d/a/daytona_1.webp','Плід великого розміру, видовжено-овальної форми, з відмінною, яскраво-червоною, хрусткою м\'якоттю і чудовим смаком. Гібрид характеризується прекрасними товарними якостями плодів. Це високоврожайний гібрид з великими вирівняними плодами, які не піддаються сонячним опікам. Гібрид стійкий до антракнозу.'),(49,'КАДЕТ / KADET —Буряк, Satimex','07-15','07-15','09-15','09-15','90 днів',10,'червоний','200 г','Призначений для використання в свіжому вигляді, переробки та довготривалого зберігання.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/-/c/-cadet.webp','Коренеплід вагою 200 г (покращений Детройт 2), забарвлення м\'якоті пурпурна без концентричних кілець.'),(50,'НОБОЛ / NOBOL - Буряк Столовий, Clause','07-15','07-20','09-15','09-20','90-95 днів',10,'темно-бордового кольору','200-250 г','Для ринку свіжих овочів, переробки, виробництва натуральних барвників. Ідеальний для тривалого зберігання.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/2/_/2_8_4.webp','Ранній урожайний з неперевершеними товарними якостями сорт призначений для вирощування у відкритому ґрунті. На всій території України показує стабільний і високий  результат в різних кліматичних умовах. Міцне бадилля та вертикальне розташування листя полегшують збір урожаю. Не схильний до стрілкування. '),(51,'ЧЕРВОНА КУЛЯ / KRASNIY SHAR - Буряк Столовий, Moravoseeds','07-10','07-10','09-10','09-10','до 85 днів',10,'червоно-фіолетове забарвлення','300-400 г','Сорт універсального призначення','https://agrolife.ua/media/mf_webp/jpeg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/_/1/_1_107_7.webp','Коренеплід має правильну круглу форму. Коренеплоди заглиблені в ґрунт наполовину. Оптимальна температура для росту- 15-23 С. Збір проводять у кінці вересня, до настання заморозків. Для даного сорту характерна висока врожайність, посухостійкість і скороспілість плодів.'),(52,'ГРАНАТ / GARNET - Буряк, Satimex','07-15','07-25','09-15','09-25','90-110 днів',10,'темно-червоного кольору','до 250 г','Для тривалого зберігання, переробки і вживання в свіжому вигляді.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/f/i/file_158_29.webp','Коренеплоди округлі, однорідні за формою і розміром, з гладкою шкіркою. М\'якоть рівномірного інтенсивного темно-червоного кольору без світлих радіальних кілець. Сильно потребує вологи в період проростання насіння. Зберігається до березня місяця. Стійкість до хвороб до цвітіння, посухи і холодів. Буряк реагує на внесення калійних добрив, попелу. Поливають буряк залежно від погодних умов, в період посухи 5 - 6 поливів, але не терпить перезволоження. Насіння слід висівати в прогрітий ґрунт, для фуражу не використовується. Після посіву ґрунт треба прикопати. Висівати на незатінених ділянках'),(53,'ГАРОЛЬД / GAROLD — Буряк, Spark Seeds','06-15','06-20','08-15','08-20','65-70 днів',10,'червоний','140-250 г','Плоди придатні для вживання відразу, тривалого зберігання і переробки.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/f/i/file_185_2.webp','Коренеплоди однорідні, гладкі, округлі. Внутрішня структура темно-бордового кольору, радіальні кільця відсутні або ледве видні. Коренеплоди мають високі смакові якості. Має високу стійкість до стрілкування і церкоспорозу (грибкове захворювання). Рослина вимоглива до вологи, особливо в період проростання насіння і утворення коренеплодів.'),(54,'ОПОЛЬСЬКИЙ / OPOLSKIJ — буряк, Satimex','07-15','07-25','09-15','09-25','90-100 днів',11,'червоний','300 г',' Сорт придатний для використання в свіжому вигляді, переробки та зберігання.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/o/p/opol_skaya.webp','Коренеплоди бордові, циліндричні, довжиною до 20 см., З гладкою шкіркою. М\'якоть без концентричних кілець, ніжна солодка. Коренеплоди багаті вітамінами С, В1 В2, РР, органічними кислотами, солями кальцію, марганцю і калію, містять велику кількість цукру. Слід вирощувати на багатих органічними речовинами суглинних і субпіщаних ґрунтах. Вимогливий до родючості і вологості ґрунту. Сходи не переносять заморозків'),(55,'ДЕТРОЙТ / DETROYT - буряк столовий, LibraSeeds','06-25','07-10','08-25','09-10','75-90 днів',11,'червоний','150-250 г',' Для свіжої реалізації, переробки та зберігання.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/1/-/1-1.webp','Коренеплоди округлої форми темно-червоного кольору. Сорт відрізняється високою стійкістю до перепадів температури і до розтріскування.'),(56,'ЦИЛІНДРА / CILINDRA - буряк столовий, LibraSeeds','06-20','07-10','08-20','09-10','80-90 днів',11,'червоний','220-300 г','Для свіжої реалізації, переробки та зберігання.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/f/i/file_166_48.webp','Коренеплоди вирівняні за формою, солодкі, темно-червоного кольору, без радіальних кілець. Легко переносить короткочасну посуху. Володіє високою стійкістю до хвороб.'),(57,'БРЕСКО F1 / BRESCO F1 - Буряк Столовий, Bejo','08-03','08-03','10-03','10-03','108 днів',11,'червоно-фіолетового забарвлення','150-200 г','Для свіжого споживання, переробки та зберігання.','https://agrolife.ua/media/mf_webp/jpeg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/b/r/bresko-f1-semena-svekly-stolovoj-okr-108-dn-bejo.webp','Коренеплід округлий, середнього розміру, червоно-фіолетового забарвлення, гладкий, м\'якуш фіолетовий. Розетка листя напіврозкидна. Кріплення листового апарату до коренеплоду компактне, завдяки чому збільшується корисна площа коренеплоду, що, власне, важливо при використанні буряка для варіння та іншої термічної обробки. Стійкість до квітучості та церкоспорозу. '),(58,'ГОЛДЕН АЙ / GOLDEN EYE - буряк столовий, Sakata','07-05','07-10','09-05','09-10','85-90 днів',11,'яскраво-жовтого','200-250 г','Для свіжої реалізації, переробки та зберігання.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/g/o/golden-aj-f1-semena-svekly-stolovoj-85-90-dn-okr-sakata.webp','Гладкі округлі коренеплоди із вираженою кільцеватістю. Листова розетка середнього розміру. Має м\'який солодкий смак.'),(59,'Червоний мамонт / Krasnij mamont — буряк кормовий, Hortus','07-20','07-30','09-20','09-30','100-110 днів',11,'червоний','8-9 кг','для корму худоби, дрібних домашніх тварин та птахів.','https://agrolife.ua/media/mf_webp/png/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/f/i/file_55_4.webp','Коренеплід від конічної до веретеноподібної форми з червоною шкіркою та білою м\'якоттю. Легко висмикується із ґрунту. Входить до харчового раціону худоби, дрібних свійських тварин і птахів, містить велику кількість вуглеводів, вітамінів і мінеральних солей. Містить менше води і більше цукру, ніж будь-який інший сорт, що робить його найбільш поживним і стимулюючим виробництво молока. Добре зберігається, якщо захищений від підмерзання.'),(60,'РЕНОВА / RENOVA - Буряк, Moravoseed','08-15','08-20','10-15','10-20','125-130 днів',12,'червоний','180-350г','Призначений для переробки і зберігання.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/s/v/svekla-renova-1.webp','Коренеплоди циліндричної форми, гладкі. М\'якуш насичений, соковитий, червоного кольору. Зберігаються коренеплоди добре, смакові якості і зовнішній вигляд не втрачаються. Догляд: необхідно проріджувати, розпушувати, в посуху поливати.');
INSERT INTO `sorts_veg` VALUES (61,'Буряк столовий Бікорес (Bikores)','08-10','08-15','10-10','10-15','120-125 днів',12,'червоний','250-450 г','вирощується для кулінарії, переробки та зберігання.','https://vesnodar.com.ua/image/cache/webp/catalog/products/semena-svekly-stolovoy-bikores-700x700.webp','Демонструє високу активність росту і врожайність незалежно від зони зростання, але оптимально підходить для південних регіонів України. Має добре розвинену кореневу систему, завдяки чому успішно протистоїть посухам, а також інтенсивно нарощує масу і отримує максимум корисних речовин з ґрунту. Не має схильності до церкоспорозу. Буряк Бікорес округлої форми, вирівняний по величині. Шкірка гладенька, темно-бордова. М\'якоть насичено-бордового кольору, без радіальних кілець, помірно-солодка на смак, про що свідчить високий вміст цукру і сухих речовин. Урожай можна збирати механізованим способом, зберігати протягом декількох місяців, вживати в їжу в свіжому або термічно обробленому вигляді.'),(62,'Буряк столовий Буллет','07-20','07-30','09-20','09-30','100-110 днів',12,'червоний','400-500 грам','для зберігання','https://images.prom.ua/4115345527_nasinnya-buryaka-stolovogo.jpg','Сорт стійкий до хвороб. Коренеплоди округлої форми мають гладку поверхню, відмінні смакові якості. М\'якуш соковитий, ніжний, солодкий, темно-червоного кольору з бордовим відтінком. Лежкість відмінна. Росте на родючих, легких ґрунтах. Особливо потребує вологи в період проростання насіння, утворення та зростання коренеплодів.'),(63,'Кукурудза цукрова рання золота','06-22','06-30','08-22','08-30','62-70 днів',13,'Бурштиновий, жовтий','240г','Використовують у вареному і консервованому вигляді зерно в молочній стиглості.','https://images.prom.ua/3529689030_w640_h640_3529689030.jpg','Рослина середньоросла. Качан слабо конусовидної форми, довжиною 19-25см, бурштинове зерно. Смакові якості свіжо відварених качанів високі. Рослини кукурудзи схильні до утворення пасинків. Тому, коли вони досягнуть висоти 20-25 см, їх пасинкують. Догляд за рослинами полягає в систематичному розпушуванні міжрядь, виполюванні бур\'янів у рядках і 1-2 підгортання. Останнє сприяє утворенню повітряних корінців, в результаті чого підвищується стійкість рослин до вилягання, поліпшується поживний режим.'),(64,'Кукурудза цукрова Делікатесна','06-28','06-30','08-28','08-30','68-70 днів',13,'жовтий','235г','Використовують у вареному і консервованому вигляді качани молочної стиглості','https://images.prom.ua/3529689026_w640_h640_3529689026.jpg','Рослина середньоросла. Качан слабо конусовидної форми, довжиною 21-26 см, зерно жовте. Смакові якості свіжо відварених качанів високі. Рослини кукурудзи схильні до утворення пасинків. Тому, коли вони досягнуть висоти 20-25 см, їх пасинкують. Догляд за рослинами полягає в систематичному розпушуванні міжрядь, виполюванні бур\'янів у рядках і 1-2 підгортання. Останнє сприяє утворенню повітряних корінців, в результаті чого підвищується стійкість рослин до вилягання, поліпшується поживний режим. Качани збирають у фазі молочно-воскової стиглості зерна. У цей період обгорткові листя щільно облягають качани і стають світло-зеленими, коси чорніють, зерно добре виповнене і набуває жовтуватого відтінку, шкіра легко ріжеться нігтем. Пізніше зерно зморщується, твердне і погано розварюється, в результаті чого кулінарна якість його знижується. Якщо зібрані качани немає можливості відразу використовувати їх з обгортками можна зберігати до 20 днів при температурі 0 ° С. При більш високій температурі качани швидко втрачають цукор, твердіють і через 2-3 дні стають непридатними для використання в кулінарії.'),(65,'Кукурудза Бандюель','06-30','07-02','08-30','09-02','71-73 дні',13,'жовтий','220-250 г','Продукція використовується для консервування, заморожування та вживання в свіжому вигляді','https://images.prom.ua/3529697714_w640_h640_3529697714.jpg','Високоврожайний гібрид цукрової кукурудзи. Рослина середньоросла, висотою 190-198 см. Голова велика, злегка конусоподібна, довжиною 17-19 см. Смакові якості свіжозвареної капусти високі. Гібрид відрізняється високою стійкістю до багатьох захворювань. Рослина жаростійка і посухостійка.'),(66,'Кукурудза Хуторянка','06-30','07-02','08-30','09-02','71-73 дні ',13,'жовтий','150-170г','Продукція використовується для консервування, заморожування та вживання в свіжому вигляді','https://images.prom.ua/3529704122_w640_h640_3529704122.jpg','Середньорослий сорт. Коренеплід конічної форми, довжиною 13-15см, діаметром 3,5-4,5. Зерно ніжне, помаранчеве, дуже солодке. Смакові якості вареної і консервованої продукції хороші. Зерно є цінним дієтичним продуктом, багате вітамінами, вуглеводами, білками.'),(67,'Кукурудза цукрова Білосніжка','07-10','07-15','09-10','09-15','80-85 днів',14,'білий','220-240г','Продукція використовується для консервування, заморожування і для споживання в свіжому вигляді','https://images.prom.ua/3529688682_w640_h640_3529688682.jpg','Високоврожайний гібрид цукрової кукурудзи. Рослина детермінантна, висотою до 190см. Качан великий, циліндричної форми, довжиною 20-22см, колір зерна - білий. Смакові якості свіжо відварених качанів високі. Гібрид відрізняється високою стійкістю до багатьох захворювань.'),(68,'Кукурудза цукрова Брусниця','07-15','07-26','09-15','09-26','85-96 днів',14,'оранжево-жовтий','220 г','Використовують у вареному і консервованому вигляді качани молочної зрілості.','https://images.prom.ua/3529689025_w640_h640_3529689025.jpg','Рослина середньоросла – 175-190 м. Початок слабоконусоподібної форми, середній, довжиною 22-25 см. Зерно оранжево-жовте. Смакові якості відмінні. Рослини кукурудзи схильні до утворення пасинків. Тому, коли вони досягнуть висоти 20-25 см, їх пасинкують. Догляд за рослинами полягає в систематичному розпушуванні міжрядь, виполюванні бур\'янів у рядках і 1-2 підгортання. Останнє сприяє утворенню повітряних корінців, в результаті чого підвищується стійкість рослин до вилягання, поліпшується поживний режим. Розпушувати ґрунт у міжряддях і підгортати рослини доцільніше після дощу або поливу.'),(69,'Кукурудза цукрова Медунка','07-05','07-05','09-05','09-05','75 днів',14,'білий','150-170г','Продукція використовується для консервування, заморожування і для споживання у свіжому вигляді.','https://images.prom.ua/3529689028_w640_h640_3529689028.jpg','Найкращий гібрид з зерном білого кольору. Рослина детермінантна, висотою 187-201см. Качан циліндричної форми, довжиною 17-19 см, діаметром 4,5 см. Посухостійкість та жаростійкість висока. Гібрид відрізняється високою стійкістю до багатьох захворювань. '),(70,'Кукурудза Багратіон','07-04','07-08','09-04','09-08','74 – 78 днів',14,'жовтий','220-250 г','Продукція використовується для консервування, заморожування і для споживання у свіжому вигляді.','https://images.prom.ua/3529697713_w640_h640_3529697713.jpg','Високоврожайний гібрид цукрової кукурудзи. Рослина середньоросла, 180-190 днів заввишки. Голова велика, циліндричної форми, довжиною більше 20 см. Смакові якості свіжозвареної капусти високі. Гібрид відрізняється високою стійкістю до багатьох захворювань. Рослина жаростійка і посухостійка.'),(71,'Кукурудза Золотий бантам','07-11','07-20','09-11','09-20','81-90 днів',14,'жовтий','170-200г','Відмінно підходить для варіння, консервації та заморозки','https://images.prom.ua/5103879630_w640_h640_5103879630.jpg','Високоврожайний суперсолодкий сорт. Рослина середньоросла, висотою 160-180см. Качан – великий, циліндричної форми, довжиною 16-19см. Зерно яскраво-жовте, вміст цукрів 17%. Смакові якості свіжо відварених качанів високі. Сорт відрізняється високою стійкістю до багатьох захворювань. Рослина жаростійка і засухостійка. Рослинам потрібен полив, прополка, розпушування та підживлення.'),(72,'Кукурудза цукрова Куликівська','07-09','07-12','09-09','09-12','79-82 дні',14,'жовтий','150-210 г','Використовують у вареному і консервованому вигляді качани молочної стиглості.','https://images.prom.ua/3529689027_w640_h640_3529689027.jpg','Рослина середньоросла – 170 см. Качан слабко конусовидної форми, довжиною 21-26 см. Посухостійка, відносно стійка до полеглості.'),(73,'Кукурудза Суперсолодка','07-04','07-08','09-04','09-08','74-78 днів',14,'жовтий','220-250г','Продукція використовується для консервування, заморожування і для споживання у свіжому вигляді.','https://images.prom.ua/3529704120_w640_h640_3529704120.jpg','Високоврожайний гібрид цукрової кукурудзи. Рослина середнерослое, заввишки 180-190см. Качан великий, циліндричної форми, довжиною більше 20см. Зерно яскраво-жовтого кольору, вміст цукрів більше 12%. Смакові якості свіжо відварених качанів високі. Гібрид відрізняється високою стійкістю до багатьох захворювань. Рослина жаростійке і посухостійка.'),(74,'Кукурудза Оверленд F1l','07-13','07-13','09-13','09-13','83 дні',15,'жовтий','200-300 г','Продукція використовується для консервування, заморожування і для споживання у свіжому вигляді.','https://images.prom.ua/4276439108_w640_h640_4276439108.jpg','Рослина середньої висоти, до 2-2,2 м, з великим листям і потужною кореневою системою. Не вимоглива до ґрунтової вологи, здатна активно розвиватися і плодоносити в найпосушливіших регіонах України навіть без регулярного зрошення. Формує 2 качани на кущі. Качани циліндричні, добре заповнені, яскраво-жовті. Середня довжина - 21-22 см, діаметр - 5-5,5 см. Зерна великі, соковиті, блискучі, зібрані в щільні, рівні ряди. Не змінюють сортового кольору при збиранні в спеку, зберіганні, термообробці. Мають насичено-солодкий смак і привабливий, товарний вигляд. Стійкість: до кукурудзяної іржі, вірусу мозаїки та бактеріальних плямистостей.'),(75,'Помідор Смугасте серце','06-20','06-25','08-20','08-25','110-115 днів',16,'червоний','150-250 г','Ідеально підходить для салатів, виготовлення соку, кетчупу.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/tomat-smugaste-serce_1.jpg?1735611840','Томат Смугасте серце - рідкісний і дуже декоративний сорт. Кущ заввишки 60-100см . Плоди червоні з поздовжніми жовтими смужками, красивої серцеподібної форми, солодкі, соковиті. Сорт стійкий до хвороб.'),(76,'Помідор Чорний імператор ','06-10','06-15','08-10','08-15','100 - 105 днів',16,'рожево-коричневий','150 - 200 г','Ідеально підходить для салатів, виготовлення соку, кетчупу.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/tomat-chorniy-imperator_1.jpg?1735612200','Томат Чорний імператор - високий, середньостиглий, неймовірно врожайний сорт. Кущ просто ломиться від плодів. Плоди красиві, рожево-коричневі, із зеленими плічками біля плодоніжки, гарного солодкого смаку. Дуже гарний і смачний у засолюванні.'),(77,'Помідор Кібіц','06-20','06-25','08-20','08-25','110-115 днів',16,'червоний','50 - 60 г','використовується в основному для літніх салатів і для цільноплідного консервування.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/tomat-kibic_1.jpg?1735612200','Томат Кібіц - подовженої форми вирізняється раннім дозріванням. Кущ детермінантний, низькорослий 50-60 см. За роки вирощування цей сорт зібрав безліч позитивних відгуків, завдяки смачним солодким плодам з невеликою кислинкою і високій стійкості рослини до захворювань і шкідників. Дуже смачні виходять з них свіжі страви та салати. За необхідності можна відправити товар на переробку. Придатність до транспортування у нього висока, так само як і товарні характеристики.'),(78,'Помідор перцевидний','06-14','06-20','08-14','08-20','104 - 110 днів',16,'червоний','100 - 120 г','використовується в основному для літніх салатів і для цільноплідного консервування.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/tomat-percevidniy_1.jpg?1735612560','Томат перцевидний - середньоранній сорт з екзотичними за формою плодами. Рослини індетермінантні, висотою 1,6-1,8 м. Ошатності рослині надають яскраво-червоні подовжено-перцевидні з гострим носиком плоди.'),(79,'Помідор Золоте гроно','06-05','06-22','08-05','08-22','95 - 112 днів',16,'жовтий','25 - 30 г','Для вживання у свіжому вигляді, салатів','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/tomat-zolote-grono_1.jpg?1735612560','Томат Золоте гроно - чудовий десертний смак, солодкий як родзинки. Суперранній індетермінатний сорт. Кущ висотою 1,5-1,8 м, потребує підв\'язки. Утворює потужні красиві золотисто-помаранчеві плоди. Солодкі, щільні, соковиті, неймовірно смачні плоди відрізняються транспортабельністю, підвищеним вмістом цукрів і вітамінів. Сорт посухостійкий, добре переносить негоду.'),(80,'Помідор Чорний дракон','06-10','06-15','08-10','08-15','100 - 105 днів',16,'червоно-коричневе','27 - 30 г','Рекомендується для консервування, в\'ялення, має оригінальний вигляд у салатах.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/tomat-chorniy-drakon_1.jpg?1735612560','Томат Чорний дракон - ранньостиглий гібрид для вирощування у відкритому і захищеному ґрунті. Рослина компактна з укороченими міжвузлями і блакитно-зеленим листям. Плоди округлі з невеликим гострим носиком, гладкі, щільні, з яскравим глянцем. Забарвлення незрілого плоду темно-фіолетове із зеленою плямою, зрілого - червоно-коричневе. Вирізняється насиченим тонким ароматом, гарним смаком і високим вмістом лікопіну та антоціанів.');
INSERT INTO `sorts_veg` VALUES (81,'Помідор Волове Серце','06-10','06-27','08-10','08-27','100-117 днів',17,'червоний','500 - 600 г','Для вживання у свіжому вигляді, салатів','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/tomat-byche-serdce-semena_1.jpg?1735772040','Середньоранній сорт з величезними серцеподібними плодами. Помідори м\'ясисті й дуже солодкі, з невеликою кількістю насіння. Кущі потужні, 120-160 см заввишки, їх рекомендується вирощувати на шпалерах у відкритому або закритому ґрунті.'),(82,'Помідор Рожевий велетень','06-25','07-05','08-25','09-05','115 - 125 днів',17,'червоний','200 - 300 г','Для вживання у свіжому вигляді, салатів','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/tomat-rozovyy-velikan_1.jpg?1735772400','Помідор рожевий Велетень – це чудовий сорт для літніх салатів. Кущі потужні, середньої висоти, близько 130 см. плоди великі і красиві, ніжно-рожевого забарвлення. У кисті 4-7 плоско округлі помідорів з соковитою м\'якоттю, прекрасного смаку.'),(83,'Помідор Чіо-Чіо-Сан','07-01','07-10','09-01','09-10','120 - 130 днів',17,'червоний','30 - 50 г','Для вживання у свіжому вигляді, салатів','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/tomat-chio-chio-san_1.jpg?1735772760','Помідор Чіо-Чіо-Сан – середньостиглий сорт. Кущі індетермінантні, близько 2 м заввишки, тому вимагають підв\'язки до колів або шпалер. Помідори нагадують довгі сливи. Вони рожеві, відрізняються прекрасним десертним смаком. Врожайність з одного куща складає 4 кг. Плоди розвиваються на величезних кистях, де їх може бути до півсотні. Стійкий до вірусу тютюнової мозаїки. '),(84,'Помідор Груша жовта','06-20','06-25','08-20','08-25','110 - 115 днів',17,'жовтий','80 - 100 г','Для вживання у свіжому вигляді, салатів','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/tomat-grusha-jeltaya_1.jpg?1735773120','Помідор Груша жовта - потужна, високоросла рослина, індетермінантна (до 2 м). Підходить для вирощування в теплицях і відкритому грунті в регіонах з м\'яким кліматом. Даний сорт відрізняється жовтими грушеподібними плодами з великим вмістом міоцину. Томати допомагають очищати організм від шкідливих речовин, відновлювати склад крові. Крім того жовті плоди менш калорійні і не викликають алергічних реакцій.'),(85,'Помідор Лимонний гігант','07-10','07-10','09-10','09-10','130 днів',17,'жовтий','250 - 500 г','Для вживання у свіжому вигляді, салатів','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/tomat-limonnyy-gigant_1.jpg?1735773120','Помідор лимонний гігант-оригінальний, великоплідний сорт. Рослина формує кущ сильнорослий, до двох метрів заввишки, плоско-округлі багатокамерні, лимонно-жовтого забарвлення плоди. Томати цінуються за транспортабельність, універсальність переробки і смакові якості.'),(86,'Помідор Аметистова коштовність','06-10','06-25','08-10','08-25','100 - 115 днів',17,'червоно-чорний','150 - 210 г','Для вживання у свіжому вигляді, салатів','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/tomat-ametistova-dorogocinnist-gl-seeds_1.jpg?1735773120','Помідор Аметистова коштовність - плоди округлої, сплюснутої форми. Шкірочка у зрілих помідорів Аметистової коштовності досить щільна, не схильна до розтріскування. У плодів відсутня кислинка, характерна для томатів. Десертний солодкий, майже карамельний.'),(87,'Помідор Банан червоний','06-10','06-20','08-10','08-20','100 - 110 днів',17,'червоний','260 - 300 г','Для вживання у свіжому вигляді, салатів','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/tomat-banan-chervoniy-gl-seeds_1.jpg?1735773480','Помідор Банан червоний - скоростиглий низькорослий сорт, рекомендований для відкритого ґрунту і тимчасових плівкових укриттів. Висота рослини 70 см. Плоди подовженої форми, довжиною 10-12 см, ідеальні для цільноплідного консервування. Урожайність однієї рослини 2,5-3,0 кг. Сорт цінують за дружну віддачу врожаю, хорошу лежкість, чудовий смак. Вирощують розсадним способом. Потребує помірного пасинкування. Можна формувати у 2-3 стебла'),(88,'Помідор Лимонне серце','06-20','06-30','08-20','08-30','110 - 120 днів',17,'жовтий','100 - 300 г','Для вживання у свіжому вигляді, салатів','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/tomat-limonnoe-serdce_1.jpg?1735773480','Помідор Лимонне серце - сорт середнього терміну дозрівання, що відрізняється великими жовтими плодами. У помідор цього сорту яскравий і насичений не тільки колір, але і смак і запах. Плоди масою до 300 г ви отримаєте після першого збору врожаю. Другий урожай, який рекомендується пустити на консервацію, буде вже трохи біднішим - помідори вагою близько 100 г.'),(89,'Помідор Чорний китай','06-20','06-25','08-20','08-25','110 - 115 днів',17,'чорний','200 - 300 г','використовують для прикрашання страв, а також додають у салати і закуски.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/tomat-chorniy-kitay_1.jpg?1735773840','Помідор Чорний Китай - новий середньоранній високоврожайний сорт, привертає до себе увагу унікальним забарвленням. До повного дозрівання стає практично чорним. Сорт індетермінантний, висотою до 1,7 м, потрібне встановлення опор. Незважаючи на ефектний зовнішній вигляд, смак у нього класичний, трохи солодкуватий з освіжаючою кислинкою. Посадку насіння на розсаду проводять на початку весни, пересадку розсади в ґрунт не раніше травня, після закінчення зворотних заморозків. Підходить для плівкових укриттів і відкритого ґрунту. Відрізняється високою стійкістю до захворювань.'),(90,'Помідор Японськи трюфель','06-25','07-05','08-25','09-05','115 - 120 днів',17,'чорно-коричневий','150 - 200 г','ідеально підходить для салатів, цільноплідного консервування і тривалого зберігання.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/tomat-yaponskiy-trufel-chorniy-gl-seeds_1.jpg?1735773840','Помідор Японський трюфель чорний - сорт рідкісного незвичайного чорно-коричневого забарвлення і дивовижного смаку. Плоди у вигляді трюфеля, м\'ясисті, в китиці 5-6 плодів, форма плоду грушоподібна з поздовжніми реберцями. Володіє незвичайним смаком, щільною консистенцією.'),(91,'Помідор Фіолетовий','06-10','06-20','07-20','07-30','110 - 120 днів',17,'пурпурно-фіолетовий','180 - 200 г','Підходять для салатів і бутербродів.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/tomat-fioletoviy_1.jpg?1735773840','Помідор Фіолетовий - унікальний середньостиглий салатний сорт томату. Рослина середньоросла досягає у висоту 1-1,2 м. Плоди плоско-округлі, пурпурно-фіолетові, відмінного смаку. Смак насичений, свіжий, солодкий і злегка терпкий, м\'ясисті, соковиті. У розрізі плід темно-бордовий. Пігмент, що міститься в бузкових томатах, сприяє зниженню ризику захворювання на рак і порушення діяльності серця.'),(92,'Помідор Чорний принц','06-10','06-20','07-20','07-30','110 - 115 днів',17,'чорний','300 - 400 г','Для вживання у свіжому вигляді, салатів','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/tomat-chorniy-princ_1.jpg?1735774200','Помідор Чорний принц - справжній делікатес на вашому городі! Відрізняється яскравим темно-червоним забарвленням з шоколадним відтінком, неповторним вишуканим смаком. Кущ може бути висотою до 2,5 м, тому його потрібно підв\'язувати.'),(93,'Помідор Король-гігант f1','06-10','06-20','07-20','07-30','110 - 115 днів',17,'червоний','600 - 800 г','Для вживання у свіжому вигляді, салатів','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/tomat-korol-gigant-f1_1.jpg?1735774200','Помідор Король-гігант F1 - ефектний індетермінантний середньостиглий колекційний сорт з плодами гігантами. Кущ потужний, висотою до 2,5 м. Плоди округлої форми, вишневого кольору, дуже великі, м\'ясисті, вирощується на шпалерах, з обов\'язковим пасинкуванням. Для отримання плодів-гігантів залишають по 2-3 квітки на кисті.'),(94,'Помідор Цифомандра','06-20','07-05','07-30','08-15','120 - 135 днів',17,'червоний','150 - 200 г','Для вживання у свіжому вигляді, салатів','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/tomat-cifomandra_1.jpg?1735774200','Помідор Цифомандра - середньостиглий сорт. Відрізняється сорт потужним і високим кущем. Розміри його можуть бути від 180 см і до 2 м. Тому біля рослини при посадці встановлюють опору. Плоди яскраво-червоні, округлі. М\'якоть характеризується кисло-солодким смаком. Помідори великі. Особливості вирощування: сорт Цифомандра підходить для вирощування в незахищеному ґрунті або на грядках в плівковій теплиці.'),(95,'Помідор Зебра біла','06-25','07-05','08-05','08-15','115 - 120 днів',17,'білий','50 - 100 г','Для вживання у свіжому вигляді, салатів','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/tomat-zebra-bila_1.jpg?1735774560','Помідор Зебра біла - популярний великоплідний середньостиглий сорт. Формує чудові, характерні плоско-округлі плоди білого або молочно-лимонного кольору із зеленими смужками. М\'якоть щільна, відмінного солодко-томатного смаку. Кущ досягає висоти понад 1,5 метра і потребує підв\'язки. Салатного призначення.'),(96,'Помідор Хурма','06-20','07-05','07-30','08-15','110 - 120 днів',17,'жовтий','250 - 300 г','Рекомендується використовувати плоди свіжими, для приготування салатів і різних гарнірів.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/tomat-hurma_1.jpg?1735774560','Помідор Хурма - середньоранній сорт з великими плодами. Кущ потужний, пагони сильні. Рослина порівняно невисока - сягає не більше 80 см. Плоди жовті, з відтінком золотого. Помідори, крім забарвлення, відрізняються м\'ясистістю, соковитістю і приголомшливим оригінальним смаком. Однією з головних переваг сорту є його лежкість і здатність не втрачати товарний вигляд навіть після тривалого транспортування.'),(97,'Помідор Смарагдове яблуко','06-15','06-30','07-25','08-10','105 - 120 днів',17,'зелений','200 - 250 г','Для вживання у свіжому вигляді, салатів','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/tomat-izumrudnoe-yabloko_1.jpg?1735774920','Помідор Смарагдове Яблуко - зелені томати, томат Смарагдове яблуко відрізняється насиченим зеленим кольором і приємним солодким смаком. Це великий м\'ясистий сорт із соковитою м\'якоттю і великою кількістю камер. Висота куща 1,2-1.5 м. Плоди мають круглу, ребристу форму. Він підходить для тривалого зберігання, не розтріскується і не псується в процесі транспортування. Для посіву варто взяти живильний торф\'яний субстрат, спочатку насіння обробляють епіном, потім заглиблюють на 1-2 см у вологий ґрунт. Перші сходи з\'являться всього через 7-10 днів, після цього рослини починають регулярно поливати, підживлюючи розсаду раз на 4 тижні. До пересадки вони будуть готові через 60 днів, до цього моменту повністю прогріється ґрунт. Варто стежити, щоб у процесі вегетації вода не застоювалася біля коріння, а швидко йшла в ґрунт. Місце краще вибрати сонячне, без вітру і з глибоким заляганням ґрунтових вод. Вирощування не складне, потрібні лише регулярні поливи, підживлення і розпушування ґрунту.'),(98,'Помідор Цукровий бізон','07-05','07-15','08-15','08-25','125 - 130 днів',17,'червоний','200 - 250 г','Для вживання у свіжому вигляді, салатів','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/tomat-saharnyy-bizon_1.jpg?1735774920','Помідор Цукровий бізон належить до індетермінантних гібридів з середнім терміном дозрівання високою врожайністю. Плоди володіють витягнутою округлою формою з рожевим відтінком.'),(99,'Помідор Лабадо f1','06-20','07-05','07-30','08-15','110 - 125 днів',17,'червоний','180 - 200 г','Для вживання у свіжому вигляді, салатів','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/tomat-labado-f1_1.jpg?1735774920','Помідор Лабадо - високоврожайний гібридний сорт. Належить до детермінантного типу томатів. Плоди цього сорту круглі, яскраво-червоні. М\'якоть досить щільна. Помідори Лабадо не тріскаються.'),(100,'Помідор Вернісаж','06-25','07-05','08-05','08-15','115 - 125 днів',17,'червоний','40 - 60 г','вживають не тільки у свіжому вигляді, але і консервують, роблять сік, соуси, кетчупи, в\'ялять на зиму.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/tomat-vernisaj_1.jpg?1735775280','Помідор Вернісаж - середньостиглий сорт, відрізняється високою врожайністю і стійкістю до захворювань. На кисті зазвичай в\'яжеться п\'ять-сім плодів. У сушеному вигляді сорт Вернісаж зберігає всі свої корисні властивості і використовується для приготування великої кількості оригінальних страв.');
INSERT INTO `sorts_veg` VALUES (101,'Помідор Де-Барао помаранчевий','07-05','07-15','08-15','08-25','120 - 130 днів',18,'помаранчевий','60 - 100 г','Томати цього сорту можна консервувати, засолювати, в\'ялити, використовувати для свіжої салатної нарізки.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/tomat-de-barao-oranjevyy_1.jpg?1736152920','Помідор Де-Барао помаранчевий – сорт із необмеженим ростом куща (до 2 м). Плоди мають сливоподібну форму та забарвленні в життєрадісний помаранчевий колір. Шкірочка щільна, пружна. М\'якуш дуже смачний, соковитий. '),(102,'Помідор Де-Барао рожевий','07-05','07-15','08-15','08-25','120 - 130 днів',18,'рожевий','60 - 90 г','Для вживання у свіжому вигляді, салатів','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/tomat-de-barao-rozovyy_1.jpg?1736152920','Помідор Де-Барао рожевий – високоросла рослина з потужним стеблом. Відрізняється високою врожайністю, гарним імунітетом і тривалим плодоношенням, впритул до холодів. Самі помідори ростуть гронами, до 10 штук на кожній гілці, мають витончену краплеподібну форму та насичений рожевий колір.'),(103,'Помідор Бобкат F1','07-05','07-15','08-15','08-25','120 - 130 днів',18,'червоний','250 - 300 г','Для вживання у свіжому вигляді, салатів','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/tomat-bobkat-f1-semena_1.jpg?1736153280','Помідор Бобкат F1 - середньоранній, детермінантний, низькорослий великоплідний високоврожайний гібрид. Кущ потужний, добре облиственний, потребує опори. Плоди формуються майже одночасно. Плоди великі, щільні, гладкі, oкpуглo-пpиплюcнутoї форми, не розтріскуються. Забарвлення плодів яскраво-червоне, без зеленого обведення. М\'якоть плодів м\'ясиста, дуже смачна. Плоди довго і добре зберігаються при транспортуванні на далекі відстані. Підходить для реалізації в свіжому вигляді і переробки. Гібрид призначений для вирощування у відкритому грунті.'),(104,'Помідор Перцевидний','07-15','08-05','08-25','09-15','135 - 150 днів',18,'червоний','120 - 150 г','Ці томати гарні в салатах і соусах, але в усьому блиску проявляють себе при в\'яленні.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/tomat-percepodibniy-yaskrava_1.jpg?1736153280','Помідор Перцевидний - приголомшливий новий сорт з незвичайними плодами. Рослини індетермінантні, висотою 1,8-2 м, середнього терміну дозрівання. Червоні, м\'ясисті, схожі на перчики. Важкі китиці, в кожній з яких 5-7 томатів, бажано підв\'язувати до опори.'),(105,'Помідор Шапка Мономаха','06-25','07-05','08-05','08-15','115 - 125 днів',18,'червоний','500 - 800 г','Для вживання у свіжому вигляді, салатів','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/tomat-shapka-monomaha_1.jpg?1736153280','Помідор Шапка Мономаха - належить до пізньостиглих сортів, з хорошим терміном зберігання. Кущі виростають до 150 см. Смак насичений солодкуватий, десертний. Сорт ще цінують за стійкість до захворювань. Насіння томату садять наприкінці зими, для цього вибирають торф\'яні поживні ґрунти з температурою +20-25°С. Глибина посадки 1-2 см. Перші паростки з\'являються через 12-14 днів, розсада добре росте і розвивається з регулярним поливом, підживленням і додатковим підсвічуванням. У травні висаджують розсаду у відкритий ґрунт або парник.'),(106,'Картопля Каменський','05-10','05-20','06-10','06-20','50 - 60 днів',19,'червоний','110 - 130 г','Для пригутування різних страв','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/e5333c423bac5a6139d5981ce6c7a3b8.jpg?1736155080','Картопля Каменський – ранній столовий сорт. Кущ прямостоячий темно-зелений з великим жорстким листям. Бульби овальної подовженої форми, з червоною шорсткою шкіркою і невеликими вічками. Вершково-жовта м\'якоть не темніє в процесі чищення і термічної обробки. З одного куща збирають 15-25 бульб. Стійкість до раку, фітофторозу, зморшкуватої і полосатої мозаїки, колорадського жука.'),(107,'Рів\'єра','05-05','05-20','06-05','06-20','45 - 60 днів',19,'жовтий','100 - 180 г','Для пригутування різних страв','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/kartofel-rivera_1.jpg?1736155440','Рів\'єра – надранній сорт картоплі столового призначення. Рослина досягає висоти 85 см, не цвіте. Відрізняється сильною кореневою системою і високою врожайністю. Коренеплоди овальної або круглої форми, шкірка шорстка, блідо-жовта. Вічка неглибокі. М\'якоть кремового відтінку з вмістом крохмалю до 16%. В одному кущі – 8-12 бульб. Стійкість до збудника раку, вірусних інфекцій, картопляної нематоди. Здатність до зберігання – 4-5 місяців.'),(108,'Картопля Удача','05-20','06-10','06-20','07-10','60 - 80 днів',19,'жовтий','100 - 150 г','Для пригутування різних страв','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/c199cd3fd466fd1cd9e4445272461108.jpg?1736155440','Картопля Удача відноситься до ранніх сортів. Бульби округлі, рівні, гладкі, матові.  Тонка шкірка світлого кремового або жовтуватого забарвлення з темними вічками. М\'якоть – біла, при варінні трохи жовтіє. Вміст крохмалю – 14%. Висока стійкість до хвороб: мозаїки, мокрої гнилі, парші. Морозостійка, зберігається 5 місяців.'),(109,'Картопля Лідер','05-25','06-10','06-25','07-10','65 - 80 днів',19,'жовтий','90 - 130 г','Використовують відвареною, для смаження, для приготування салатів і картоплі фрі','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/d08165eb5ec79d8438e9f632c4474f8d.jpg?1736155800','Лідер – ранньостиглий столовий сорт картоплі з відмінними смаковими якостями. Бадилля висотою до 1 м, листя невелике. Бульби овально-круглої форми.  Шкірка світло-жовта з невеликими вічками. М\'якоть кремова з 12% вмістом крохмалю. Стійкий до збудників раку.'),(110,'Картопля Ред Скарлет','05-30','06-05','06-30','07-05','70 - 75 днів',19,'червоний','60 - 140 г','Підходить для смаження, відварювання, для приготування чіпсів, картоплі фрі','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/kartofel-red-skarlet_1.jpg?1736155800','Картопля Ред Скарлет – ранній сорт голландського походження. Рослина низька, прямостояча. З одного куща збирають до 15 бульб. Бульби овальні, довгі, з тонкою шкіркою червоно-малинового кольору. Вічка практично непомітні. Колір сирої м\'якоті – білий або світло-жовтий, не темніє при обробці.'),(111,'Картопля Імпала','05-10','05-20','06-10','06-20','50 - 70 днів',19,'жовтий','90 - 150 г','підходить для запікання, смаження, приготування супів і салатів. ','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/kartofel-impala_1.jpg?1736155800','Кущ картоплі Імпала прямостоячий, густий, досягає у висоту 75 см. Плоди – овальні, з товстою гладенькою шкіркою жовтого забарвлення з середніми вічками. З куща збирають до 12 бульб. М\'якоть жовтого або кремового відтінку містить близько 14% крохмалю, не темніє при термічній обробці, розварюється середньо. Сорт володіє хорошими смаковими якостями. Стійкість до картопляного раку, нематоди, парші, фітофторозу. '),(112,'Картопля Беллароза','05-10','05-20','06-10','06-20','50 - 60 днів',19,'рожевий','120 - 210 г','Для пригутування різних страв','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/kartofel-bellaroza_1.jpg?1736156160','Картопля Беллароза – ранній сорт столового призначення. Один кущ може формувати 8-9 картоплин. У них рожева шкірка й молочно-жовта м\'якоть, вона розсипчаста, має прекрасний смак. Картопля прекрасно переносить навіть тривалі посушливі періоди. '),(113,'Картопля Королева Анна','05-25','06-05','06-25','07-05','75 - 80 днів',19,'жовтий','85 - 140 г','Для пригутування різних страв','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/4475e1d77b7d8eddbe05fa1067cc4db7.jpg?1736156160','Картопля Королева Анна – це високоврожайний ранньостиглий сорт. Бульби великі, мають злегка витягнуту форму. Шкірка із жовтим забарвленням, м\'якоть бульб рівномірно-жовта. Сорт дає прекрасні врожаї на будь-якому типі ґрунту. Вміст крохмалю в м\'якоті збільшується в сухе літо.'),(114,'Картопля Ассоль','05-15','05-25','06-15','06-25','55 - 65 днів',19,'жовтий','80 - 140 г','Сорт призначений для сезонного споживання та непогано зберігається у зимові місяці.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/kartofel-assol_1.jpg?1736156160','Картопля Ассоль - це ранньостиглий сорт. Бульби овальні, шкірка жовта та шорстка. М\'якоть крохмалиста, смачна, розсипчаста, має жовто-солом\'яний відтінок.'),(115,'Картопля Імператриця','05-20','06-10','06-20','07-10','60 - 80 днів',19,'жовтий','75 - 150 г','Для пригутування різних страв','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/kartofel-imperatrica_1.jpg?1736156520','Картопля Імператриця – це ранньостиглий сорт столового призначення. М\'якоть смачна, м\'яка, добре розварюється. У кожному кущі 7–10 бульб, близьких за розміром. Це відмінний сорт для будь-якої кліматичної зони. Термін повного циклу розвитку становить всього 2-3 місяці: у теплому кліматі можна отримати 2 врожаю за сезон.'),(116,'Картопля Торнадо','05-10','05-20','06-10','06-20','50 - 65 днів',19,'рожевий','90 - 120 г','Бульби придатні для тривалого зберігання й широкого використання в кулінарії.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/kartofel-tornado_1.jpg?1736156520','Картопля Торнадо – це унікальний ранній сорт, підходить для будь-якого клімату й типу ґрунту. Один кущ приносить до 20 овальних бульб середнього розміру з яскравою малиновою шкіркою та білою крохмалистою м\'якоттю. У південних регіонах можна збирати 2 врожаю за сезон.'),(117,'Картопля Скороспілка','05-05','05-10','06-05','06-10','45 - 50 днів',19,'жовтий','120 - 150 г','Для пригутування різних страв','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/kartoplya-skorospilka_1.jpg?1736156520','Картопля Скороспілка – ранній сорт столового призначення. Урожайність висока. З одного куща вдається зібрати до 15 бульб. Бульби смачні та мають гарний товарний вигляд для продажу.'),(118,'Картопля Фермер','05-10','05-20','06-10','06-20','50 - 60 днів',19,'жовтий','90 - 120 г','Для пригутування різних страв','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/kartofel-fermer_0.jpg?1736156880','Картопля Фермер – це ранньостиглий сорт, який часто вирощують в комерційних цілях. Два врожаї на рік.'),(119,'Картопля Мілена','05-30','06-20','06-30','07-20','70 - 90 днів',19,'жовтий','120 - 210 г','Для пригутування різних страв','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/kartofel-milena_0.jpg?1736156880','Картопля Мілена – це ранньостиглий сорт, в теплому кліматі можна висаджувати двічі за сезон. Добре підходить для всіх типів ґрунту, пристосовується до особливостей місця зростання. Врожайність висока, м\'якоть із середнім вмістом крохмалю, зберігає форму при варінні. Смак відмінний, підходить для будь-яких страв.'),(120,'Картопля Невська','06-10','06-30','07-10','07-30','80 - 95 днів',19,'жовтий','90 - 130 г','Для пригутування різних страв','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/kartoplya-nevska_1.jpg?1736156880','Картопля Невська користується популярністю та відноситься до середньоранніх сортів. Кущі картоплі низькі, прямостоячі, мають безліч гіллястих стебел. Під час цвітіння у рослини з’являється безліч білих квіток, проте опадають вони теж швидко. Завдяки своїй потужній кореневій системі рослина може поглинати вологу з нижніх шарів ґрунту. За рахунок цього досягається висока посухостійкість. У спекотну погоду широкі листя не дають волозі швидко випаровуватися. Шкірка гладка, жовтувата, з рожевими очима. Почищена м’якоть довго не темніє і має ніжно-біле забарвлення. Картопля не розварюється і тримає форму. Вона зберігає відмінні смакові якості як при приготуванні, так і при смаженні.');
INSERT INTO `sorts_veg` VALUES (121,'Картопля Синьоочка','06-15','07-05','07-15','08-05','85 - 100 днів',20,'жовтий','160 - 165 г','Для пригутування різних страв','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/kartofel-sineglazka_1.jpg?1736157240','Сорт картоплі Синьоочка – середньостиглий. Рослина велика, стебла міцні. Коренеплоди овальні, трохи приплюснуті.  Шкірка сіро-рожева з синюватою пігментацією. Вічка темні, неглибокі. М\'якоть біла, не змінює колір при обробці, містить 15% крохмалю. Легко засвоюється, рекомендується для дитячого і дієтичного харчування.'),(122,'Ласунок','06-10','07-10','07-10','08-10','80 - 120 днів',20,'жовтий','150 - 200 г','Для пригутування різних страв','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/kartofel-lasunok_1.jpg?1736157240','Ласунок – відомий середньопізній сорт картоплі. За якостями вважається одним із найсмачніших. Кущі потужні, високі, з жорстким листям. Великі бульби круглоовальної форми. Шкірка ясно-жовтого відтінку з середніми вічками, м\'якоть кремова.'),(123,'Картопля Гурман','05-30','06-10','06-30','07-10','70 - 80 днів',20,'фіолетовий','100 - 120 г','Вважається дієтичним продуктом, вживається сирою у салати, підходить для приготування супів, варіння у «мундирах», для запікання.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/kartofel-gurman_1.jpg?1736157240','Картопля Гурман відноситься до кольорових сортів. Кущі досягають висоти 70 см. Бульби овальної форми, з щільною шкіркою темно-фіолетового кольору. З одного куща можна зібрати 12-14 бульб. М\'якоть фіолетового забарвлення з білими краями. '),(124,'Картопля Роко','06-15','06-30','07-15','07-30','85 - 95 днів',20,'рожевий','75 - 120 г','Для пригутування різних страв','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/kartofel-rokko_1.jpg?1736157600','Картопля Роко – один з столових сортів. Рослина висотою 50 см, прямостояча, з маленькими листочками. Бульби округлі, шкірка тонка гладка, рожевого кольору з жовтою пігментацією. М\'якоть бежевого кольору володіє відмінним смаком, не змінює колір при варінні. Вміст крохмалю – 12-16%.'),(125,'Картопля Альвара','05-25','06-05','06-25','07-05','75 - 80 днів',20,'рожевий','70 - 122 г','Для пригутування різних страв','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/kartofel-alvara_1.jpg?1736157600','Картопля Альвара відноситься до середньоранніх сортів. Кущ заввишки до 80 см, листя зелене. Бульби овальної форми, покриті гладкою червоною шкіркою, володіють відмінними смаковими якостями, не розварюються. М\'якоть на розрізі світло-жовтого кольору, не міняє колір в процесі переробки.'),(126,'Картопля Санте','06-10','06-30','07-10','07-30','80 - 90 днів',20,'жовтий','100  - 150 г','Сорт Санте підходить найкращим чином для приготування картоплі фрі, смаженої картоплі, для заправки супів, запікання і фарширування.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/kartoplya-sante_1.jpg?1736157960','Картопля Санте – сорт голландського походження. Кущі компактні, невеликі, середньої висоти. Коренева система розвинена добре, за рахунок чого бульби рясно розвиваються. З одного куща городники збирають до 20 картоплин. Особливістю сорту Санте є мала частка крохмалю. Це говорить про те, що картопляні бульби при приготуванні не будуть розварюватися, а будуть зберігати свою форму. Бульби володіють відмінним смаком, очищені від шкірки, довго не темніють.'),(127,'Картопля Пікассо','07-10','08-10','08-10','09-10','120 - 150 днів',21,'жовтий','80 - 140 г','Для пригутування різних страв','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/kartofel-pikasso_1.jpg?1736157960','Картопля Пікассо – пізньостиглий сорт. Рослина висока, листя велике, темно-зелене. Назву Пікассо картопля світло-жовтого забарвлення отримала в честь картин знаменитого художника з «рожевого періоду» його творчості. Бульбоплоди овальної форми, шкірка блідо-жовтого кольору з неглибокими вічками яскраво-червоного забарвлення. Бульби великі, рівні.  Крохмалистість невисока – до 12%. Картопля не розварюється, має приємний смак і аромат, підходить для приготування різноманітних видів страв. Зберігається до глибокої весни, не проростаючи, зберігає свій вигляд, не в\'яне.'),(128,'Огірок-корнішон Конні F1','06-10','06-20','07-20','07-30','40 - 45 днів',22,'зелений','90 - 110 г','Для пригутування різних страв','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/ogurec-kornishon-konni-f1_1.jpg?1736159760','Огірок-корнішон Конні F1 – це гібрид, який добре зарекомендував себе за 20 років існування: середньоранній, не потребує запилення комахами, утворює зав\'язь пучками від 3 до 9 штук, дружно починає плодоносити. Огірки темно-зелені з дрібними горбиками, без гіркоти, їм не властиве переростання.'),(129,'Огірок Бочковий F1','06-10','06-20','07-20','07-30','40 - 45 днів',22,'зелений','80 - 100 г','Дуже добре підходить для засолювання у діжках, консервації, для приготування свіжих салатів.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/ogurec-bochkovoy-f1_1.jpg?1736159760','Огірок Бочковий F1 – ранньостиглий гібридний сорт із цвітінням переважно жіночого типу. Зеленці з темно-зеленою шкіркою виростають не більше, ніж на 9 см. Огірковий букет (3-4 шт.) складається з округло-циліндричних плодів, покритих дрібними пухирцями. Регулярне збирання огірків сприяє розвитку нових зав\'язей.'),(130,'Огірок Малюк','06-10','06-20','07-20','07-30','40 - 45 днів',22,'зелений','50 - 70 г','ідеальний для засолювання та маринування.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/ogurec-malysh_1.jpg?1736159760','Огірок Малюк – скоростиглий бджолозапилювальний сорт огірків з темно-зеленими горбистими плодами корнішонного типу. Мініатюрний розмір солодких, без гіркоти зеленців (5-10 см).'),(131,'Огірок-мінікорнішон Капелька F1','06-10','06-20','07-20','07-30','40 - 45 днів',22,'зелений','60 - 80 г','Активно використовуються для приготування свіжих салатів і делікатесної закуси. ','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/ogurec-minikornishon-kapelka-f1_1.jpg?1736160120','Огірок-мінікорнішон Капелька F1 - відмінний варіант для збору середнього врожаю. Середньоплетиста рослина плодоносить невеликими огірками до 10 см, хоча їх починають збирати вже при досягненні 3-4 см.'),(132,'Огірок Китайський жаростійкий F1','06-15','06-25','07-25','08-05','45 - 55 днів',22,'зелений','до 100 г','Підходить для приготування легких і соковитих свіжих салатів.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/ogirok-gibrid-kitayskiy-jarostiykiy-f1_1.jpg?1736160120','Огірок Китайський жаростійкий F1 - середньоранній, суперврожайний гібрид для відкритого ґрунту і плівкових теплиць. Стійкий до підвищених температур (+30 °С і вище). Рослини потужні, гіллясті, плоди в зрілому вигляді досягають 35-50 см заввишки.'),(133,'Огірок Аристократ F1','06-12','06-17','07-22','07-27','42 - 45 днів',22,'зелений','80 - 100 г','Ідеально підходять для засолювання та консервування.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/ogirok-partenokarpik-aristokrat-f1_1.jpg?1736160120','Огірок Аристократ F1 - прекрасний ранньостиглий партенокарпічний гібрид. Кущ потужний, жіночого типу цвітіння і букетного закладення зав\'язей. Корнішони короткі, вирівняні, циліндричної форми, темно-зелені, без внутрішніх пустот, хрусткі, без гіркоти. Стійкий до стресових умов. Для вирощування у відкритому та захищеному ґрунті. Стійкий до несправжньої борошнистої роси.'),(134,'Огірок Король грядки F1','06-15','06-25','07-25','08-05','45 - 55 днів',22,'зелений','80 - 100 г','Використовуються у свіжому вигляді, для засолювання і маринування.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/ogirok-gibrid-korol-gryadki-f1_1.jpg?1736160120','Огірок Король грядки F1 - це скоростиглий бджолозапильний гібрид з високою насиченістю жіночими квітками. Стійкий до несправжньої борошнистої роси і несприятливих умов. Призначений для вирощування у відкритому ґрунті. Великобугорчастий бурошипий огірок без гіркоти досягає 9-11 см завдовжки. Плоди зеленого забарвлення зі світлими смугами. У пазусі листка утворюється по 1-3 зав\'язі. '),(135,'Огірок Водограй F1','06-10','06-20','07-20','07-30','40 - 45 днів',22,'зелений','80 - 100 г','Використовуються у свіжому вигляді, для засолювання і маринування.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/ogurec-vodogray-f1_1.jpg?1736160480','Огірок Водограй F1 – ранньостиглий гібрид для вирощування у відкритому ґрунті. Він формує невеликі плоди 11-13 см завдовжки. В діаметрі зеленці досягають 3-4 см. Шкірка має помітні горбки, вона не схильна до пожовтіння навіть при переростанні.'),(136,'Огірок Голубчик F1','06-15','06-25','07-25','08-05','45 - 55 днів',23,'зелений','80 - 100 г','Для салатів і зимової заготівлі.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/ogurec-golubchik-f1_1.jpg?1736160480','Огірок Голубчик F1 – гібридний сорт з високою врожайністю. Плоди розміром до 11 см мають рівномірне зелене забарвлення, не переростають. Можна збирати огірочки дрібнішого розміру – це не позначається на смакових якостях. Шкірка тонка, ніжна. М\'якуш із яскраво вираженим огірковим смаком. '),(137,'Огірок Цезар F1','06-20','06-25','07-30','08-05','50 - 55 днів',23,'зелений','80 - 120 г','Для салатів і зимової заготівлі.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/ogurec-cezar-f1_1.jpg?1736160480','Огірок Цезар F1 – це гібридний сорт польської селекції. За тривалістю дозрівання належить до середньоранніх. Смак зеленців відмінний, великі шипи легко знімаються, забезпечуючи рівномірне проникнення маринаду в м\'якоть.'),(138,'Огірок Білий ангел','06-20','06-25','07-30','08-05','50 - 55 днів',23,'білий','90 - 100 г','Для салатів і зимової заготівлі.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/ogirok-biliy-yangol-gl-seeds_1.jpg?1736160840','Огірок Білий ангел - посухостійкий екзотичний середньоранній гібрид. Плоди овально-циліндричні, крупнобугорчасті, довжиною 1518 см, оригінального кремово-білого забарвлення. Шкірка тонка, ніжна, м\'якоть соковита. '),(139,'Огірок Новий Ніжинський F1','06-20','06-22','07-30','08-01','50 - 52 дні',23,'зелений','70 - 130 г','ідеально підходять для вживання у свіжому вигляді та в салатах, а також для приготування виключно смачних малосольних і маринованих огірочків.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/ogirok-noviy-nijinskiy-f1-gl-seeds_1.jpg?1736160840','Огірок Новий Ніжинський F1 - чудовий середньостиглий бджолозапильний гібрид характеризується відмінними засолювальними якостями, за смаком і врожайністю перевершує класичний сорт. Вирівняні хрусткі крупнобугорчасті зеленці красивого яскраво-зеленого кольору. '),(140,'Огірок Білий делікатес','06-15','06-25','07-25','08-05','45 - 55 днів',23,'зелений','120 - 160 г','Рекомендується для споживання у свіжому вигляді та для консервування.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/ogirok-sortoviy-biliy-delikates_1.jpg?1736160840','Огірок Білий делікатес - оригінальний сорт китайської селекції з екзотичним забарвленням плодів. Середньостиглий, високоврожайний, прекрасно росте як у плівкових теплицях, так і у відкритому ґрунті. Плоди довжиною 12-14 см, подовжено-конічної форми, горбкуваті, з дуже ніжною шкіркою, смачні. Сорт стійкий до захворювань, посухо і морозостійкий. ');
INSERT INTO `sorts_veg` VALUES (141,'Огірок Пуччіні','06-10','06-13','07-20','07-23','40 - 43 дні',23,'зелений','60 - 110 г','Вживають у свіжому вигляді, консервують.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/ogurec-komnatnyy-puchchini-semena_1.jpg?1736161200','Огірок кімнатний Пуччіні володіє хорошими смаковими якостями: плоди не гірчать. Серединка відрізняється рівномірною структурою, шкірка тонка, темно-зеленого кольору. '),(142,'Огірок Рацібор F1','06-15','06-20','07-25','07-30','45 - 50 днів',23,'зелений','90 - 130 г','Основне призначення сорту – засолювання. У свіжому вигляді сорт добре підходить для приготування літніх салатів. ','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/ogurec-racibor-f1_1.jpg?1736161200','Огірок Рацібор F1 – це середньостиглий сорт зі смачними хрусткими зеленцями. Рослина стійка до пероноспорозу і деяких інших захворювань. Плоди не мають гіркого смаку, не утворюють порожнини всередині при приготуванні.'),(143,'Огірок Вісконсін','06-20','06-28','07-30','08-08','50 - 58 днів',23,'зелений','90 - 110 г','Рекомендується для споживання у свіжому вигляді та для консервування.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/ogurec-viskonsin_1.jpg?1736161200','Огірок Вісконсін – це середньоранній сорт. Зеленці збирають на стадії технічної стиглості, коли вони досягають розміру 8-10 см. Плоди зелені з дрібними шипами, які легко знімаються. М\'якоть щільна, хрустка, ароматна.'),(144,'Огірок Китайські змії','06-15','06-25','07-25','08-05','45 - 55 днів',23,'зелений','до 350 г','Рекомендується для споживання у свіжому вигляді та для консервування.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/ogirok-sortoviy-kitayski-zmii_1.jpg?1736161560','Огірок Китайські змії - оригінальний салатний сорт з довгими, тонкими, надзвичайно ніжними плодами темно-зеленого забарвлення з короткою шийкою. Довжина плодів досягає 40-60 см. Цей сорт любить поживні ґрунти, тепле і вологе місце зростання. Насіння дуже чутливе до холоду, тому не висівати занадто рано. '),(145,'Огірок Руфус F1','06-15','06-25','07-25','08-05','45 - 55 днів',23,'зелений','80 - 100 г','Рекомендується для споживання у свіжому вигляді та для консервування.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/ogirok-rufus-f1-sadiba-centr_1.jpg?1736161920','Огірок Руфус F1 - стабільно врожайний салатний і засолювальний гібрид. Сорт середньостиглий, стійкий до основних хвороб огірків. Зеленці дуже красиві, насичено-зелені, з великими горбками. Відрізняються високою якістю: ніколи не гірчать, без пустот і не жовтіють.'),(146,'Огірок Китайське диво','07-10','07-20','08-10','08-20','60 - 70 днів',24,'зелений','250 - 400 г','Рекомендується для споживання у свіжому вигляді та для консервування.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/ogirok-kitayske-divo-yaskrava_1.jpg?1736161560','Огірок Китайське диво - рідкісний довгоплідний огірок, може вирости до 50 см. Його довгі витягнуті зеленці покриті гладкою темно-зеленою шкіркою. Вони вважаються одним з найкращих салатних сортів з ніжним соковитим смаком, хорошою хрусткістю і без натяку на гіркоту.'),(147,'Огірок Ізід F1','07-10','07-15','08-10','08-15','60 - 65 днів',24,'зелений','90 -110 г','Рекомендується для споживання у свіжому вигляді та для консервування.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/ogurec-izid-f1-semena_1.jpg?1736161560','Огірок Ізід F1 – пізньостиглий гібрид, який довго плодоносить. Плоди дрібні – до 10 см у довжину, усіяні маленькими горбочками, соковиті. Смачні у свіжому вигляді.'),(148,'Огірок Універсальний F1','06-15','06-28','07-25','08-08','45 - 58 днів',23,'зелений','80 - 100 г','Рекомендується для споживання у свіжому вигляді та для консервування.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/ogirok-universalniy-f1-yaskrava_1.jpg?1736161920','Огірок Універсальний F1 - найурожайніший гібрид для відкритого ґрунту, при цьому сорт володіє високими смаковими якостями, хрумтить у свіжому і консервованому вигляді. Огірочки низькокалорійні, підходять для дієтичного харчування. М\'якоть містить вітаміни В, А, С, калій, тому сприяє поліпшенню роботи всього організму, включно з серцем. Гібриди дозрівають відносно швидко, зеленці збирають все літо, вони відмінно транспортуються, зберігаючи товарні якості понад один тиждень.'),(149,'Огірок Забава F1','06-10','06-20','07-20','07-30','40 - 45 днів',23,'зелений','80 - 120 г','Рекомендується для споживання у свіжому вигляді та для консервування.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/ogurec-zabava-f1_1.jpg?1736161920','Огірок Забава F1 – комахозапильний середньостиглий гібридний сорт корнішонного типу. Рекомендується культивувати під плівковим укриттям або у відкритому ґрунті. Це потужна і високоврожайна рослина, з переваженим цвітінням за жіночим типом. Огірочки насичено зеленого кольору, циліндричної форми, опушені, з великими горбками. Їх довжина не перевищує 12 см.'),(150,'Огірок Кураж F1','06-08','06-15','07-18','07-25','38 - 45 днів',22,'зелений','120 - 130 г','Рекомендується для споживання у свіжому вигляді та для консервування.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/ogurec-kuraj-f1-semena_1.jpg?1736162280','Огірок Кураж F1 має світло-зелені зеленці покриті горбиками і білими шипами. ');
